css:
.countryrisk-sim-container {
    padding: 28px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: 'Courier New', 'SF Mono', monospace;
    color: #e0e6f0;
}
.countryrisk-sim-header {
    border-left: 4px solid #ff6b35;
    padding: 24px 28px;
    margin-bottom: 24px;
    background: rgba(255,107,53,0.05);
    position: relative;
}
.countryrisk-sim-header-badge {
    position: absolute;
    top: 16px;
    right: 20px;
    background: rgba(239,68,68,0.15);
    color: #ef4444;
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    padding: 4px 12px;
    border-radius: 3px;
    border: 1px solid rgba(239,68,68,0.3);
}
.countryrisk-sim-header h1 {
    color: #ff6b35;
    font-size: 1.5rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin: 0 0 6px 0;
}
.countryrisk-sim-header p {
    color: #8892a4;
    font-size: 0.85rem;
    margin: 0;
}
.countryrisk-sim-period-counter {
    text-align: center;
    font-size: 0.9rem;
    color: #6b7280;
    margin-bottom: 22px;
    text-transform: uppercase;
    letter-spacing: 0.12em;
}
.countryrisk-sim-period-counter span {
    margin: 0 4px;
}
.countryrisk-sim-period-counter #currentDay {
    color: #ff6b35;
    font-weight: 700;
    font-size: 1.3rem;
}
.countryrisk-sim-briefing {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-left: 3px solid #00bfff;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 24px;
}
.countryrisk-sim-briefing h3 {
    color: #00bfff;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin: 0 0 14px 0;
}
.countryrisk-sim-briefing p {
    color: #c9d1d9;
    font-size: 0.85rem;
    line-height: 1.7;
    margin: 0;
    font-family: -apple-system, 'Segoe UI', sans-serif;
}
.countryrisk-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 24px;
}
.countryrisk-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px 16px;
    position: relative;
    overflow: hidden;
    text-align: center;
    transition: transform 0.2s ease;
}
.countryrisk-sim-kpi-card:hover {
    transform: translateY(-3px);
}
.countryrisk-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
}
.countryrisk-sim-kpi-cash::before {
    background: linear-gradient(90deg, #ff6b35, #ff9f1c);
}
.countryrisk-sim-kpi-exposure::before {
    background: linear-gradient(90deg, #ef4444, #f97316);
}
.countryrisk-sim-kpi-risk::before {
    background: linear-gradient(90deg, #eab308, #f59e0b);
}
.countryrisk-sim-kpi-cds::before {
    background: linear-gradient(90deg, #8b5cf6, #a78bfa);
}
.countryrisk-sim-kpi-label {
    color: #6b7280;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 10px;
}
.countryrisk-sim-kpi-value {
    font-size: 1.9rem;
    font-weight: 700;
}
.countryrisk-sim-kpi-cash .countryrisk-sim-kpi-value {
    color: #ff6b35;
}
.countryrisk-sim-kpi-exposure .countryrisk-sim-kpi-value {
    color: #ef4444;
}
.countryrisk-sim-kpi-risk .countryrisk-sim-kpi-value {
    color: #eab308;
}
.countryrisk-sim-kpi-cds .countryrisk-sim-kpi-value {
    color: #a78bfa;
}
.countryrisk-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 26px;
    margin-bottom: 24px;
}
.countryrisk-sim-controls h3 {
    color: #e0e6f0;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 0 0 22px 0;
    padding-bottom: 14px;
    border-bottom: 1px solid #1f2d3d;
}
.countryrisk-sim-controls-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
    margin-bottom: 24px;
}
.countryrisk-sim-control-group label {
    display: block;
    color: #9ca3af;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 8px;
}
.countryrisk-sim-control-group input[type="number"] {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 4px;
    padding: 11px 14px;
    width: 100%;
    font-family: 'Courier New', monospace;
    font-size: 1.15rem;
    font-weight: 600;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    box-sizing: border-box;
}
.countryrisk-sim-control-group input[type="number"]:focus {
    border-color: #ff6b35;
    outline: none;
    box-shadow: 0 0 10px rgba(255,107,53,0.2);
}
.countryrisk-sim-control-group small {
    display: block;
    color: #4b5563;
    font-size: 0.68rem;
    margin-top: 7px;
    font-family: -apple-system, 'Segoe UI', sans-serif;
}
.countryrisk-sim-btn-row {
    display: flex;
    gap: 14px;
    align-items: center;
}
.countryrisk-sim-submit-btn {
    background: linear-gradient(135deg, #ff6b35, #ff9f1c) !important;
    border: none !important;
    color: #0a0f1e !important;
    font-weight: 700;
    font-family: 'Courier New', monospace;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding: 12px 36px;
    border-radius: 4px;
    font-size: 0.85rem;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    cursor: pointer;
}
.countryrisk-sim-submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(255,107,53,0.3);
}
.countryrisk-sim-undo-btn {
    border-color: #2d3f55 !important;
    color: #6b7280 !important;
    font-family: 'Courier New', monospace;
    font-size: 0.78rem;
    transition: color 0.2s ease;
}
.countryrisk-sim-undo-btn:hover {
    color: #9ca3af !important;
}
.countryrisk-sim-chart-section {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 22px;
    margin-bottom: 24px;
    height: 320px;
}
.countryrisk-sim-history {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 22px;
    overflow-x: auto;
}
.countryrisk-sim-history table {
    color: #c9d1d9;
    font-size: 0.78rem;
    margin-bottom: 0;
}
.countryrisk-sim-history table thead th {
    color: #6b7280;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.68rem;
    border-color: #1f2d3d;
    background: #0d1321;
}
.countryrisk-sim-history table td {
    border-color: #1f2d3d;
    vertical-align: middle;
}
.countryrisk-sim-history table tbody tr:hover {
    background: rgba(255,107,53,0.04);
}
@media (max-width: 768px) {
    .countryrisk-sim-container {
        padding: 16px;
    }
    .countryrisk-sim-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
    }
    .countryrisk-sim-controls-grid {
        grid-template-columns: 1fr;
    }
    .countryrisk-sim-kpi-value {
        font-size: 1.4rem;
    }
    .countryrisk-sim-btn-row {
        flex-direction: column;
    }
    .countryrisk-sim-submit-btn {
        width: 100%;
    }
    .countryrisk-sim-header-badge {
        position: static;
        display: inline-block;
        margin-bottom: 12px;
    }
    .countryrisk-sim-chart-section {
        height: 250px;
    }
}

/* [EQIL v1.1.0] end-of-simulation debrief (namespaced, append-only) */
.countryrisk-sim-cm { padding: 20px; background: #111827; border: 1px solid rgba(0,191,255,0.25); border-radius: 12px; color: #e0e6f0; }
.countryrisk-sim-cm-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-bottom: 10px; }
.countryrisk-sim-cm-badge { font-size: 12px; letter-spacing: 0.08em; text-transform: uppercase; color: #0a0f1e; background: #00bfff; padding: 4px 10px; border-radius: 999px; font-weight: 700; }
.countryrisk-sim-cm-verdict { font-size: 18px; font-weight: 700; color: #ff6b35; }
.countryrisk-sim-cm-profit { font-size: 40px; font-weight: 800; color: #00bfff; line-height: 1.1; margin-bottom: 14px; font-family: 'Courier New', monospace; }
.countryrisk-sim-cm-kpis { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 14px; }
.countryrisk-sim-cm-kpis > div { display: flex; flex-direction: column; gap: 2px; background: rgba(0,191,255,0.08); padding: 8px 12px; border-radius: 8px; }
.countryrisk-sim-cm-kpis span { font-size: 11px; color: #8892a4; text-transform: uppercase; letter-spacing: 0.04em; }
.countryrisk-sim-cm-kpis strong { font-size: 16px; color: #e0e6f0; font-family: 'Courier New', monospace; }
.countryrisk-sim-cm-insights { margin: 0; padding-left: 20px; }
.countryrisk-sim-cm-insights li { margin: 6px 0; color: #c9d1d9; line-height: 1.5; }
@media (max-width: 640px) { .countryrisk-sim-cm-kpis { grid-template-columns: 1fr; } }

