            state.domainState.cash += netProfit;
            state.domainState.totalRevenue += totalRevenue;
            state.domainState.totalCosts += productionCost + hedgingCost;
            state.domainState.totalExposure += arsRevenue;
            state.domainState.currentCDS = round.cdsLevel;

            var riskScore = Math.round((round.cdsLevel / 300) * (1 - d.hedgingPercent / 100) * (1 - d.contractPercentUSD / 100) * 10) / 10;
            state.domainState.currentRiskScore = riskScore;

            state.domainState.npvHistory.push(Math.round(netProfit));
            state.domainState.revenueHistory.push(Math.round(totalRevenue));
            state.domainState.riskHistory.push(riskScore);
            state.domainState.cdsHistory.push(round.cdsLevel);

            // platform score: total net profit so far (sum of npvHistory, the same rounded netProfit values getPerformanceSummary adds up) mapped through its tier thresholds,
            // beginner 0-39 up to 40000, competent 40-64 up to 120000, proficient 65-84 up to 200000, expert 85-100 up to 1050000 (four full-volume all-USD rounds)
            var pfTotal = 0;
            for (var pfi = 0; pfi < state.domainState.npvHistory.length; pfi++) { pfTotal += state.domainState.npvHistory[pfi]; }
            var pfAvg = pfTotal / Math.max(1, state.domainState.npvHistory.length);
            var pfScore = 39 * Math.max(0, pfTotal) / 40000;
            if (pfTotal > 200000 && pfAvg > 50000) pfScore = 85 + 15 * Math.min(1, (pfTotal - 200000) / 850000);
            else if (pfTotal > 120000 && pfAvg > 25000) pfScore = 65 + 19 * Math.min(1, (pfTotal - 120000) / 80000);
            else if (pfTotal > 40000) pfScore = 40 + 24 * Math.min(1, (pfTotal - 40000) / 80000);
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(pfScore))) });

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                volume: Math.round(volume),
                grossRevenue: Math.round(grossRevenue),
                productionCost: Math.round(productionCost),
                usdRevenue: Math.round(usdRevenue),
                arsRevenue: Math.round(arsRevenue),
                fxLoss: Math.round(fxLoss),
                hedgingCost: Math.round(hedgingCost),
                hedgingRecovery: Math.round(hedgingRecovery),
                shockOccurred: shockOccurred,
                shockLoss: Math.round(shockLoss),
                defaultOccurred: defaultOccurred,
                defaultLoss: Math.round(defaultLoss),
                netProfit: Math.round(netProfit),
                riskScore: riskScore,
                cash: Math.round(state.domainState.cash),
                cdsLevel: round.cdsLevel
            };
        }

