        getPerformanceSummary(history) {
            if (!history.length) return {};
            var profits = history.map(function(r) { return r.results ? r.results.netProfit || 0 : 0; });
            var totalProfit = profits.reduce(function(s, p) { return s + p; }, 0);
            var avgProfit = totalProfit / profits.length;
            var totalHedgingCost = history.reduce(function(s, r) { return s + (r.results ? r.results.hedgingCost || 0 : 0); }, 0);
            var shockCount = history.filter(function(r) { return r.results && r.results.shockOccurred; }).length;
            var defaultCount = history.filter(function(r) { return r.results && r.results.defaultOccurred; }).length;

            var t = function(k){ try { return window.mySimulation.t(k); } catch(e){ return k; } };
            var tier = 'beginner';
            if (totalProfit > 200000 && avgProfit > 50000) tier = 'expert';
            else if (totalProfit > 120000 && avgProfit > 25000) tier = 'proficient';
            else if (totalProfit > 40000) tier = 'competent';

            var insights = [];
            if (totalProfit > 200000) insights.push(t('insight_outstanding'));
            else if (totalProfit > 120000) insights.push(t('insight_solid'));
            else if (totalProfit > 0) insights.push(t('insight_marginal'));
            else insights.push(t('insight_loss'));
            if (shockCount > 1) insights.push(t('insight_shocks'));
            if (defaultCount > 0) insights.push(t('insight_defaults'));

            return {
                totalProfit: totalProfit,
                avgProfit: Math.round(avgProfit),
                totalHedgingCost: totalHedgingCost,
                shocksEncountered: shockCount,
                defaultsEncountered: defaultCount,
                performance: t('perf_' + tier),
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.defaultOccurred) return window.mySimulation.t('hint_default');
            if (results.shockOccurred) return window.mySimulation.t('hint_shock');
            if (results.netProfit < 0) return window.mySimulation.t('hint_loss');
            if (state.decisions.hedgingPercent < 20 && state.decisions.contractPercentUSD < 50) return window.mySimulation.t('hint_exposed');
            if (results.netProfit > 50000) return window.mySimulation.t('hint_strong');
            return null;
        }

